typedef unsigned long int big_int;
int strlen(const char *);

class stringx;
class string_buf {
protected:
  friend class stringx;
  friend stringx operator+(const stringx &, const stringx &);
  friend stringx operator+(const stringx &, const char *);
  big_int *data;
  int ref_count;
  int char_length;
};
class stringx {
  string_buf *my_buf;
public:
  stringx();
  stringx(const stringx &);
  ~stringx();
  void make_room(int);
  void append(const stringx &);
  void append(const char *, int);
  friend stringx operator+(const stringx &, const stringx &);
  friend stringx operator+(const stringx &, const char *);
};
inline stringx operator+(const stringx &lhs, const stringx &rhs) {
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}
inline stringx operator+(const stringx &lhs, const char *rhs) {
  stringx foo;
  int len = strlen(rhs);
  foo.make_room(len + lhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs, len);
  return foo;
}
class script_object_instance {
  void *owner;
  stringx name;
public:
  const stringx &get_name() const { return name; }
};
class vm_executable {
  stringx name;
  stringx fullname;
public:
  const stringx &get_fullname() const { return fullname; }
};
class vm_thread {
  script_object_instance *inst;
  const vm_executable *ex;
public:
  script_object_instance *get_instance() const { return inst; }
  const vm_executable *get_executable() const { return ex; }
};
class vm_stack {
  int salloc;
  char *buffer;
  char *SP;
  vm_thread *my_thread;
public:
  char *get_SP() const { return SP; }
  void pop(int n) { SP -= n; }
  vm_thread *get_thread() const { return my_thread; }
  bool push(const char *, int);
};
class script_library_class { public: class function { public: enum entry_t { FIRST_ENTRY, RECALL_ENTRY }; }; };
class entity;
class trigger {
  void *vtable;
  unsigned int flags;
  void *signals;
  entity *whodunnit;
public:
  entity *get_triggered_ent() const { return whodunnit; }
};
typedef trigger *vm_trigger_t;
typedef entity *vm_entity_t;
void error(const stringx &);
